namespace App\Services;use App\Domain\Workflow\ActionFailure;use Illuminate\Support\Facades\Redis;final class DownstreamThrottle{public function consume(string $organizationId,string $target,int $limit):void{if($limit<=0)return;$window=now('UTC')->format('YmdHi');$key='qf:downstream:'.hash('sha256',$organizationId.'|'.$target.'|'.$window);$count=(int)Redis::eval("local n=redis.call('INCR',KEYS[1]); if n==1 then redis.call('EXPIRE',KEYS[1],70) end; return n",1,$key);if($count>$limit)throw new ActionFailure('Downstream rate limit exceeded','rate_limit',max(1,60-(int)now()->format('s')));}}
